#!/usr/bin/env python3
"""Namespace-tolerant ARXML inventory. This is discovery, not schema or semantic validation."""
import argparse
import json
import sys
import xml.etree.ElementTree as ET
from pathlib import Path

def local_name(tag: str) -> str:
    return tag.rsplit("}", 1)[-1] if "}" in tag else tag

def child_text(element, wanted):
    for child in list(element):
        if local_name(child.tag) == wanted and child.text:
            return child.text.strip()
    return None

def walk(element, path=""):
    counts = {}
    for child in list(element):
        name = local_name(child.tag)
        counts[name] = counts.get(name, 0) + 1
        child_path = f"{path}/{name}[{counts[name]}]"
        yield child, child_path
        yield from walk(child, child_path)

def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("root", type=Path, help="ARXML file or directory")
    parser.add_argument("--out", type=Path, default=Path("engineering/traceability/arxml_inventory.json"))
    parser.add_argument("--max-bytes", type=int, default=50_000_000)
    args = parser.parse_args()
    if not args.root.exists():
        parser.error(f"Path not found: {args.root}")
    files = [args.root] if args.root.is_file() else sorted(args.root.rglob("*.arxml"))
    results, errors = [], []
    for file in files:
        if file.suffix.lower() != ".arxml":
            continue
        try:
            if file.stat().st_size > args.max_bytes:
                errors.append({"file": str(file), "error": "skipped: file exceeds size limit"})
                continue
            tree = ET.parse(file)
            root = tree.getroot()
        except (OSError, ET.ParseError) as exc:
            errors.append({"file": str(file), "error": str(exc)})
            continue
        elements = []
        tag_counts = {}
        for element, xpath in walk(root, "/" + local_name(root.tag) + "[1]"):
            tag = local_name(element.tag)
            tag_counts[tag] = tag_counts.get(tag, 0) + 1
            short_name = child_text(element, "SHORT-NAME")
            definition_ref = child_text(element, "DEFINITION-REF")
            value = child_text(element, "VALUE")
            dest = element.attrib.get("DEST")
            if short_name or definition_ref or value is not None or dest:
                elements.append({
                    "xpath": xpath, "tag": tag, "short_name": short_name,
                    "definition_ref": definition_ref, "value": value, "dest": dest
                })
        results.append({
            "file": file.as_posix(),
            "root_tag": local_name(root.tag),
            "namespace": root.tag[1:].split("}", 1)[0] if root.tag.startswith("{") else None,
            "element_count": sum(tag_counts.values()),
            "tag_counts": tag_counts,
            "indexed_elements": elements,
            "limitations": [
                "No AUTOSAR XSD validation performed.",
                "No cross-file reference resolution or ECUC semantic validation performed.",
                "XPath indices are generated by traversal and should be revalidated against the source before citing."
            ]
        })
    args.out.parent.mkdir(parents=True, exist_ok=True)
    args.out.write_text(json.dumps({"input": str(args.root), "files": results, "errors": errors}, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"ARXML files indexed: {len(results)}; errors/skipped: {len(errors)}; output: {args.out}")
    return 1 if errors else 0

if __name__ == "__main__":
    raise SystemExit(main())
